# ==============================================================================
# gnomAD v4.1 PTC SNV extraction
#
# Purpose:
#   1. Merge per-chromosome gnomAD v4.1 variant files
#   2. Identify premature termination codon (PTC)-producing variants using aenmd
#   3. Restrict the downstream analysis to single-nucleotide variants (SNVs)
#   4. Create standardized variant identifiers
#   5. Prepare variants for ANNOVAR ensGene annotation
#
# Input:
#   Per-chromosome .rds files generated by:
#   https://github.com/CobanAkdemirlab/NMDescapediseasegene_paper/
#  Specific link: https://github.com/CobanAkdemirlab/NMDescapediseasegene_paper/blob/main/variant%20level_v5/gnomad/gnomAD_downloaddata.R
# Output:
#   - gnomAD_all_aenmd.rds
#   - gnomAD_PTC_SNV.rds
#   - gnomAD_PTC_SNV.vcf
#   - gnomAD_PTC_SNV.avinput
#   - ANNOVAR ensGene annotation files
#   - gnomAD_fr.var.can_snv.RData
#
# Genome build:
#   GRCh38 / hg38
#
# Dataset:
#   gnomAD v4.1
# ==============================================================================


# ------------------------------------------------------------------------------
# 1. Configuration and helper functions
# ------------------------------------------------------------------------------

source("config.R")
source("annovar_helpers.R")


# ------------------------------------------------------------------------------
# 2. Required packages
# ------------------------------------------------------------------------------

library(GenomicRanges)
library(aenmd)
library(Biostrings)


# ------------------------------------------------------------------------------
# 3. Locate and merge per-chromosome gnomAD files
# ------------------------------------------------------------------------------

files <- list.files(
    cfg$gnomad$raw_dir,
    pattern = "\\.rds$",
    full.names = TRUE
)

if (length(files) == 0) {
    stop(
        "No gnomAD .rds files found in: ",
        cfg$gnomad$raw_dir
    )
}

message(
    "Number of chromosome files found: ",
    length(files)
)

gr_list <- lapply(
    files,
    readRDS
)

gr_all <- do.call(
    c,
    gr_list
)

message(
    "Total gnomAD variants merged: ",
    length(gr_all)
)

saveRDS(
    gr_all,
    out_path(
        cfg$gnomad,
        "gnomAD_v4.1_all_variants.rds"
    )
)


# ------------------------------------------------------------------------------
# 4. Process variants
# ------------------------------------------------------------------------------

gr_processed <- process_variants(
    gr_all
)

# Remove variants containing undefined ALT alleles
contains_N <- Biostrings::vcountPattern(
    "N",
    gr_processed$alt
) > 0

gr_processed <- gr_processed[
    !contains_N
]


# ------------------------------------------------------------------------------
# 5. Annotate premature termination codons
# ------------------------------------------------------------------------------

gr_nmd <- annotate_nmd(
    gr_processed,
    rettype = "gr"
)

gnomad_df <- as.data.frame(
    gr_nmd,
    row.names = NULL,
    optional = TRUE
)

gnomad_ptc <- gnomad_df[
    gnomad_df$res_aenmd.is_ptc %in% TRUE,
]

message(
    "PTC-producing variants before SNV filtering: ",
    nrow(gnomad_ptc)
)


# ------------------------------------------------------------------------------
# 6. Retain SNVs only
# ------------------------------------------------------------------------------

gnomad_ptc_snv <- gnomad_ptc[
    gnomad_ptc$type == "snv",
]

message(
    "PTC-producing SNVs retained: ",
    nrow(gnomad_ptc_snv)
)

saveRDS(
    gnomad_ptc_snv,
    out_path(
        cfg$gnomad,
        "gnomAD_v4.1_PTC_SNV.rds"
    )
)


# ------------------------------------------------------------------------------
# 7. Standardize chromosome and variant identifiers
# ------------------------------------------------------------------------------

gnomad_ptc_snv$CHROM <- as.character(
    gnomad_ptc_snv$seqnames
)

gnomad_ptc_snv$CHROM <- ifelse(
    grepl("^chr", gnomad_ptc_snv$CHROM),
    gnomad_ptc_snv$CHROM,
    paste0("chr", gnomad_ptc_snv$CHROM)
)

gnomad_ptc_snv$POS <- gnomad_ptc_snv$start

gnomad_ptc_snv$key <- with(
    gnomad_ptc_snv,
    paste0(
        CHROM,
        ":",
        POS,
        "_",
        ref,
        ">",
        alt
    )
)

gnomad_ptc_snv$variantID <- with(
    gnomad_ptc_snv,
    paste(
        CHROM,
        POS,
        ref,
        alt,
        sep = "_"
    )
)


# ------------------------------------------------------------------------------
# 8. Prepare VCF for ANNOVAR
# ------------------------------------------------------------------------------

vcf_out <- out_path(
    cfg$gnomad,
    "gnomAD_v4.1_PTC_SNV.vcf"
)

write_minimal_vcf(
    gnomad_ptc_snv,
    vcf_out
)


# ------------------------------------------------------------------------------
# 9. Run ANNOVAR ensGene annotation
# ------------------------------------------------------------------------------

run_annovar(
    vcf_path = vcf_out,
    out_prefix = out_path(
        cfg$gnomad,
        paste0(
            "gnomAD_v4.1_PTC_SNV_ensGene_",
            cfg$gencode_version
        )
    ),
    annovar_dir = cfg$annovar_dir,
    build = cfg$genome_build,
    dbtype = "ensGene"
)


# ------------------------------------------------------------------------------
# 10. Save standardized variant table for downstream annotation
# ------------------------------------------------------------------------------

fr.var.can <- data.frame(
    contig = gnomad_ptc_snv$CHROM,
    position = gnomad_ptc_snv$POS,
    REF_ALLELE = as.character(
        gnomad_ptc_snv$ref
    ),
    ALT_ALLELE = as.character(
        gnomad_ptc_snv$alt
    ),
    key = gnomad_ptc_snv$key,
    variantID = gnomad_ptc_snv$variantID,
    stringsAsFactors = FALSE
)

save(
    fr.var.can,
    file = out_path(
        cfg$gnomad,
        "gnomAD_v4.1_fr.var.can_snv.RData"
    )
)


# ------------------------------------------------------------------------------
# 11. Completion summary
# ------------------------------------------------------------------------------

message("gnomAD v4.1 PTC SNV extraction complete.")
message("Output directory: ", cfg$gnomad$output_dir)
